omlx/settings.json.text:
{
  "version": "1.0",
  "server": {
    "host": "127.0.0.1",
    "port": 18765,
    "log_level": "info",
    "cors_origins": [],
    "server_aliases": [
      "localhost",
      "127.0.0.1"
    ],
    "sse_keepalive_mode": "chunk",
    "auto_start_on_launch": false,
    "burst_decode_mode": "balanced",
    "preserve_mid_system_cache": false
  },
  "model": {
    "model_dirs": [
      "ROOT/run/omlx/models"
    ],
    "model_dir": "ROOT/run/omlx/models",
    "model_fallback": false,
    "hide_helper_models": false
  },
  "memory": {
    "prefill_memory_guard": true,
    "memory_guard_tier": "balanced",
    "memory_guard_custom_ceiling_gb": 0.0,
    "soft_threshold": 0.85,
    "hard_threshold": 0.95,
    "prefill_safe_zone_ratio": 0.8,
    "prefill_min_chunk_tokens": 32
  },
  "scheduler": {
    "max_concurrent_requests": 1,
    "embedding_batch_size": 8,
    "chunked_prefill": false,
    "prefill_step_size": 2048,
    "prefill_priority": "context"
  },
  "cache": {
    "enabled": false,
    "hot_cache_only": false,
    "ssd_cache_dir": "ROOT/state/cache/omlx",
    "ssd_cache_max_size": "40GB",
    "hot_cache_max_size": "0",
    "initial_cache_blocks": 256
  },
  "auth": {
    "api_key": "fixed-test-key",
    "secret_key": "fixed-test-hex",
    "skip_api_key_verification": false,
    "sub_keys": []
  },
  "sampling": {
    "max_context_window": 8192,
    "max_context_window_policy": 8192,
    "max_tokens": 1024
  },
  "logging": {
    "log_dir": "ROOT/run/logs",
    "retention_days": 7
  }
}

